def split_lane_state(apps, schema_editor):
    """Seed both lane rows per source from the shared columns.

    Interval seeding follows the cadence each lane's JOB actually ran at before
    the split: for a heartbeat source that is cadence_baseline_s for the CR-006
    repair crawl and the shared current_interval_s for the heartbeat probe; for
    a single-lane source the shared value is the full lane's and the (inert)
    heartbeat row starts at baseline. Any pending back-off window is copied to
    BOTH lanes: we cannot tell which lane earned it, and holding a source back
    too long is recoverable while hammering a source that just 429'd is not.
    """
    SourceConfig = apps.get_model("catalog", "SourceConfig")
    SourceLaneState = apps.get_model("catalog", "SourceLaneState")
    rows = []
    for config in SourceConfig.objects.all():
        hb = config.heartbeat_enabled
        rows.append(
            SourceLaneState(
                source_config=config,
                lane="full",
                current_interval_s=(config.cadence_baseline_s if hb else config.current_interval_s),
                clean_polls=0 if hb else config.clean_polls,
                backoff_until=config.backoff_until,
            )
        )
        rows.append(
            SourceLaneState(
                source_config=config,
                lane="heartbeat",
                current_interval_s=(config.current_interval_s if hb else config.cadence_baseline_s),
                clean_polls=config.clean_polls if hb else 0,
                backoff_until=config.backoff_until,
            )
        )
    SourceLaneState.objects.bulk_create(rows)


def merge_lane_state(apps, schema_editor):
    """Best-effort reverse: collapse two lanes back into the shared columns.

    Lossy by construction — the lane that did not drive the source's cadence has
    its interval and clean-poll count discarded. The surviving cadence comes from
    the heartbeat lane for a heartbeat source and the full lane otherwise, while
    the back-off window is the later of the two so no live window is dropped.
    """
    SourceConfig = apps.get_model("catalog", "SourceConfig")
    SourceLaneState = apps.get_model("catalog", "SourceLaneState")
    for config in SourceConfig.objects.all():
        states = {s.lane: s for s in SourceLaneState.objects.filter(source_config=config)}
        primary = states.get("heartbeat" if config.heartbeat_enabled else "full") or next(
            iter(states.values()), None
        )
        if primary is None:
            config.current_interval_s = config.cadence_baseline_s
        else:
            config.current_interval_s = primary.current_interval_s
            config.clean_polls = primary.clean_polls
        windows = [s.backoff_until for s in states.values() if s.backoff_until is not None]
        config.backoff_until = max(windows) if windows else None
        config.save(update_fields=["current_interval_s", "clean_polls", "backoff_until"])


